import { CommonModule } from '@angular/common';
import { Component, ElementRef, HostListener, OnDestroy, inject } from '@angular/core';
import { EMPTY, Observable, Subject, of, timer } from 'rxjs';
import { catchError, map, switchMap, tap } from 'rxjs/operators';

type Status = 'idle' | 'loading' | 'success' | 'empty' | 'error';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent implements OnDestroy {
  private readonly host = inject(ElementRef<HTMLElement>);

  readonly listboxId = 'autocomplete-listbox';

  private readonly cities: string[] = [
    'Amsterdam', 'Ankara', 'Athens', 'Austin',
    'Barcelona', 'Berlin', 'Boston', 'Brussels',
    'Chicago', 'Copenhagen',
    'Dubai',
    'Edinburgh',
    'Frankfurt',
    'Hamburg',
    'Istanbul', 'Izmir',
    'London', 'Los Angeles',
    'Madrid', 'Miami', 'Milan', 'Munich',
    'New York',
    'Oslo',
    'Paris', 'Prague',
    'Rome',
    'San Diego', 'San Francisco', 'San Jose', 'Seattle',
    'Tokyo',
    'Vienna',
    'Zurich'
  ];

  private readonly cache = new Map<string, string[]>();
  private readonly searchKey$ = new Subject<string>();

  // switchMap drops the older wait or search as soon as a new key arrives.
  private readonly searches = this.searchKey$
    .pipe(
      switchMap((key) =>
        this.resultsFor(key).pipe(
          catchError(() => {
            this.results = [];
            this.status = 'error';
            return EMPTY;
          })
        )
      )
    )
    .subscribe((results) => this.showResults(results));

  query = '';
  status: Status = 'idle';
  isOpen = false;
  activeIndex = -1;
  results: string[] = [];

  get activeId(): string | null {
    const active = this.results[this.activeIndex];
    return active ? this.optionId(active) : null;
  }

  get resultStatus(): string {
    if (this.status === 'loading') return 'Searching';
    if (this.status === 'success') {
      return this.results.length === 1 ? '1 result' : `${this.results.length} results`;
    }
    if (this.status === 'empty') return 'No results';
    if (this.status === 'error') return 'Search failed';
    return '';
  }

  ngOnDestroy(): void {
    this.searches.unsubscribe();
  }

  onInput(value: string): void {
    const key = this.queryKey(value);
    this.query = value;
    this.results = [];
    this.activeIndex = -1;
    this.status = key ? 'loading' : 'idle';
    this.isOpen = !!key;
    this.searchKey$.next(key);
  }

  onFocus(): void {
    if (this.status !== 'idle') this.isOpen = true;
  }

  onKeyDown(ev: KeyboardEvent): void {
    if (ev.key === 'Escape') {
      this.isOpen = false;
      this.activeIndex = -1;
      return;
    }

    if (ev.key === 'ArrowDown' || ev.key === 'ArrowUp') {
      ev.preventDefault();
      if (!this.isOpen) {
        if (this.status !== 'idle') this.isOpen = true;
        return;
      }

      const len = this.results.length;
      if (len === 0) return;

      if (ev.key === 'ArrowDown') {
        this.activeIndex = this.activeIndex < 0 ? 0 : (this.activeIndex + 1) % len;
      } else {
        this.activeIndex = this.activeIndex < 0 ? len - 1 : (this.activeIndex - 1 + len) % len;
      }
      return;
    }

    if (ev.key === 'Enter' && this.isOpen && this.activeIndex >= 0) {
      ev.preventDefault();
      this.select(this.results[this.activeIndex]);
    }
  }

  select(value: string): void {
    // A pick fills the input, but it is not a new search.
    this.searchKey$.next('');
    this.query = value;
    this.results = [];
    this.status = 'idle';
    this.isOpen = false;
    this.activeIndex = -1;
  }

  optionId(item: string): string {
    return 'autocomplete-option-' + item.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  }

  highlight(item: string, queryRaw: string): string {
    const q = queryRaw.trim();
    if (!q) return this.escapeHtml(item);

    const idx = item.toLowerCase().indexOf(q.toLowerCase());
    if (idx < 0) return this.escapeHtml(item);

    const before = this.escapeHtml(item.slice(0, idx));
    const mid = this.escapeHtml(item.slice(idx, idx + q.length));
    const after = this.escapeHtml(item.slice(idx + q.length));
    return `${before}<mark>${mid}</mark>${after}`;
  }

  @HostListener('document:mousedown', ['$event'])
  onDocMouseDown(ev: MouseEvent): void {
    const target = ev.target as Node | null;
    if (!target) return;
    if (!this.host.nativeElement.contains(target)) {
      this.isOpen = false;
      this.activeIndex = -1;
    }
  }

  private queryKey(rawQuery: string): string {
    return rawQuery.trim().toLowerCase();
  }

  private showResults(results: string[]): void {
    this.results = results;
    this.status = results.length ? 'success' : 'empty';
    this.isOpen = true;
    this.activeIndex = -1;
  }

  private resultsFor(key: string): Observable<string[]> {
    if (!key) return EMPTY;

    const remembered = this.cache.get(key);
    if (remembered) return of(remembered);

    return timer(300).pipe(
      switchMap(() => this.search(key)),
      tap((results) => this.cache.set(key, results))
    );
  }

  private search(key: string): Observable<string[]> {
    return timer(150).pipe(
      map(() => {
        if (key === 'error') throw new Error('Deterministic search failure');
        return this.cities
          .filter((city) => city.toLowerCase().includes(key))
          .slice(0, 8);
      })
    );
  }

  private escapeHtml(s: string): string {
    return s
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }
}

