.page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background: #0a0a0a;
  color: #e5e7eb;
  font-family: system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
}

.card {
  width: 100%;
  max-width: 520px;
  background: #0b1020;
  border: 1px solid #1f2937;
  border-radius: 14px;
  padding: 18px;
  display: grid;
  gap: 14px;
}

.title {
  margin: 0;
  font-size: 18px;
  font-weight: 800;
}

.label {
  display: block;
  font-size: 12px;
  color: #9ca3af;
  margin-bottom: 6px;
}

.combo {
  position: relative;
}

.input {
  box-sizing: border-box;
  width: 100%;
  padding: 12px 12px;
  border-radius: 12px;
  border: 1px solid #374151;
  background: #0a0f1e;
  color: #e5e7eb;
  outline: none;
}

.input:focus {
  border-color: #a3e635;
  box-shadow: 0 0 0 2px rgba(163,230,53,.15);
}

.list {
  position: absolute;
  z-index: 10;
  left: 0;
  right: 0;
  margin-top: 8px;
  max-height: 240px;
  overflow: auto;
  border-radius: 12px;
  border: 1px solid #1f2937;
  background: #0a0f1e;
}

.option {
  padding: 10px 12px;
  cursor: pointer;
  border-bottom: 1px solid rgba(31,41,55,.5);
}

.option:last-child {
  border-bottom: none;
}

.option.active {
  background: rgba(163,230,53,.12);
}

.empty {
  padding: 10px 12px;
  color: #9ca3af;
}

.hint {
  margin: 0;
  color: #9ca3af;
  font-size: 12px;
}

mark {
  background: rgba(163,230,53,.25);
  color: #e5e7eb;
  border-radius: 4px;
  padding: 0 2px;
}

.empty--error {
  color: #fecaca;
}

.result-status {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
